// logger, usage: log(this, "");
const log = global.get('logger');

// 1.  Settings
// A day only counts when the heat pump has actually been used on that day.
const MIN_RUN_POWER_W = 50;      // power above this value counts as 'running'
const MIN_DAY_ENERGY_KWH = 0.5;  // a day with less energy counts as 'not used'
const MIN_DAY_COVERAGE = 0.9;    // fraction of the day the sensors must have valid data

// 2.  Input
// Each history list is an array of HA states, as delivered by the 'Get history' nodes
const history = msg.history || {};
const SERIES = ["outside", "water", "power", "cop"];

for (const key of SERIES) {
    if (!Array.isArray(history[key]) || history[key].length === 0) {
        log(this, `History for '${key}' missing or empty`, "warn");
        node.status({ fill: "red", shape: "ring", text: `No history: ${key}` });
        return null;
    }
}

const DAY_MS = 86_400_000;
const now = Date.now();

// Local midnight of the day containing timestamp t
const dayStart = (t) => {
    const d = new Date(t);
    return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
};
const nextDayStart = (t) => {
    const d = new Date(dayStart(t));
    return new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1).getTime();
};
const dayKey = (t) => {
    const d = new Date(t);
    const pad = (v) => String(v).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};
const round = (v, digits) => (v === null || !isFinite(v)) ? null : Number(v.toFixed(digits));

// Convert HA states into time segments [start, end) with a numeric value.
// A state is valid until the next state change. Unknown / unavailable states become gaps.
function toSegments(states) {
    const points = states
        .map(s => ({
            t: new Date(s.last_changed ?? s.last_updated ?? (s.lu * 1000)).getTime(),
            v: parseFloat(s.state ?? s.s),
        }))
        .filter(p => isFinite(p.t))
        .sort((a, b) => a.t - b.t);

    const segments = [];
    points.forEach((p, i) => {
        const end = (i < points.length - 1) ? points[i + 1].t : now;
        if (isFinite(p.v) && end > p.t) segments.push({ start: p.t, end: end, v: p.v });
    });
    return segments;
}

// Split segments on local midnight and accumulate time-weighted sums per day.
// `include` decides which values take part in the average (e.g. skip COP = 0).
function perDay(segments, include = () => true) {
    const days = {};
    segments.forEach(seg => {
        let start = seg.start;
        while (start < seg.end) {
            const end = Math.min(seg.end, nextDayStart(start));
            const key = dayKey(start);
            const day = days[key] ??= { sum: 0, ms: 0, covered_ms: 0, above_ms: 0 };
            const ms = end - start;
            day.covered_ms += ms;
            if (include(seg.v)) {
                day.sum += seg.v * ms;
                day.ms += ms;
            }
            if (seg.v > MIN_RUN_POWER_W) day.above_ms += ms;
            start = end;
        }
    });
    return days;
}

// 3.  Process
const outside = perDay(toSegments(history.outside));
const water = perDay(toSegments(history.water));
const power = perDay(toSegments(history.power));
const cop = perDay(toSegments(history.cop), v => v > 0); // do not average the 0 values

const today = dayKey(now);
const rows = [];
let skipped = 0;

Object.keys(power).sort().forEach(key => {
    if (key === today) return; // incomplete day

    const p = power[key];
    const o = outside[key];
    const w = water[key];
    const c = cop[key];

    // Data must cover (almost) the full day, otherwise the averages are not representative
    if (!o || !w || p.covered_ms < MIN_DAY_COVERAGE * DAY_MS || o.covered_ms < MIN_DAY_COVERAGE * DAY_MS) {
        skipped++;
        return;
    }

    // Average over the full day: hours without data are assumed to match the measured hours
    const powerAvg = p.sum / p.ms;
    const energyKwh = powerAvg * 24 / 1000;

    // Only use days on which the heat pump has been used
    if (energyKwh < MIN_DAY_ENERGY_KWH || p.above_ms === 0) {
        skipped++;
        return;
    }

    rows.push({
        date: key,
        outside_temp_avg: round(o.sum / o.ms, 1),          // °C
        water_target_temp_avg: round(w.sum / w.ms, 1),     // °C
        power_avg: round(powerAvg, 0),                     // W, over the full day
        energy: round(energyKwh, 2),                       // kWh
        running_hours: round(p.above_ms / 3_600_000, 1),   // h
        cop_avg: c && c.ms > 0 ? round(c.sum / c.ms, 2) : null, // excludes COP = 0
    });
});

// Least squares fit y = slope * outside + intercept, gives the relation to outside temperature
function fit(key) {
    const pts = rows.filter(r => r[key] !== null && r.outside_temp_avg !== null);
    const n = pts.length;
    if (n < 2) return null;
    const mx = pts.reduce((s, r) => s + r.outside_temp_avg, 0) / n;
    const my = pts.reduce((s, r) => s + r[key], 0) / n;
    const sxx = pts.reduce((s, r) => s + (r.outside_temp_avg - mx) ** 2, 0);
    if (sxx === 0) return null;
    const sxy = pts.reduce((s, r) => s + (r.outside_temp_avg - mx) * (r[key] - my), 0);
    const slope = sxy / sxx;
    return { slope: round(slope, 3), intercept: round(my - slope * mx, 2), days: n };
}

const average = (key) => {
    const values = rows.map(r => r[key]).filter(v => v !== null);
    return values.length ? round(values.reduce((s, v) => s + v, 0) / values.length, 2) : null;
};

// 4.  Output
msg.heat_pump_history = {
    updated: new Date(now).toISOString(),
    days_used: rows.length,
    days_skipped: skipped,
    averages: {
        outside_temp_avg: average("outside_temp_avg"),
        water_target_temp_avg: average("water_target_temp_avg"),
        power_avg: average("power_avg"),
        energy: average("energy"),
        cop_avg: average("cop_avg"),
    },
    // per °C outside temperature: value = slope * outside_temp + intercept
    fit: {
        water_target_temp: fit("water_target_temp_avg"),
        power: fit("power_avg"),
        cop: fit("cop_avg"),
    },
    days: rows.sort((a, b) => a.outside_temp_avg - b.outside_temp_avg),
};

global.set("heat_pump_history", msg.heat_pump_history);
delete msg.history; // raw history is large, do not pass it on

log(this, `${rows.length} days used, ${skipped} skipped`);
node.status({ fill: "green", shape: "dot", text: `${rows.length} days | COP ${msg.heat_pump_history.averages.cop_avg ?? "-"}` });

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;
